from itertools import combinations

def E(a, b, c):
    s1 = a + b + c
    s2 = a*b + b*c + c*a
    s3 = a*b*c
    # E = (s1 * (s2 + 1)) / (4 * s3)
    numerator = s1 * (s2 + 1)
    denominator = 4 * s3

    if denominator == 0:
        return None # Should not happen for positive integers

    # We only care if the result is an integer
    if numerator % denominator == 0:
        return numerator // denominator
    return None

# Search for n=1, 2, 3 for a, b, c up to 10
max_val = 10
solutions = {1: [], 2: [], 3: []}

for a in range(1, max_val + 1):
    for b in range(a + 1, max_val + 1):
        for c in range(b + 1, max_val + 1):
            n = E(a, b, c)
            if n is not None and n <= 3:
                solutions[n].append((a, b, c))

print("Solutions found for n=1, 2, 3 (a < b < c <= 10):")
for n, sols in solutions.items():
    print(f"n={n}: {sols}")
